# Housing simulator, long texts, part 2: myth cards and the town hall. Citations (author, year) stay in English.
import json, os
K = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'hkeys.json'), encoding='utf-8'))
def mk(D):
    T = {}
    for i, v in D.items():
        pre, tr = v[0], v[1:]
        if i < len(K) and K[i].startswith(pre): T[K[i]] = tuple(tr)
    return T

T = mk({
73: ('“Why not just build skyscrapers', '“¿Por qué no construir rascacielos en todas partes?”', '“为什么不到处建摩天楼？”', '„Dlaczego nie budować wszędzie wieżowców?”'),
74: ('Towers are the priciest', 'Las torres son las viviendas más caras de construir, así que solo funcionan donde las rentas son más altas.', '塔楼是造价最高的住房，所以只在房租最高的地方行得通。', 'Wieże to najdroższe mieszkania w budowie, więc opłacają się tylko tam, gdzie czynsze są najwyższe.'),
75: ('Steel-and-concrete high-rises', 'Los rascacielos de acero y concreto cuestan unos $65–71 más por pie cuadrado que los edificios más bajos (un estudio del Terner Center sobre proyectos de California), y necesitan elevadores, cimientos profundos y más seguridad contra incendios. Salen las cuentas en el centro y junto a las estaciones más concurridas, no en la mayoría de las cuadras. La demanda también se acaba: incluso en 2021, pronosticado como su mejor año desde al menos 1999, se esperaba que el centro de Chicago llenara unos 6,500 departamentos más. La zonificación del Loop ya permite superrascacielos; lo que los frena es el costo y el financiamiento. Por eso repartir edificios de altura media y de 3 a 6 departamentos por la ciudad suma más viviendas en la simulación que amontonar torres en pocos lugares.',
    '钢筋混凝土高层楼每平方英尺的造价比矮楼高约 65–71 美元（特纳中心对加州项目的研究），还需要电梯、深地基和额外的消防设施。它们在市中心和最繁忙的车站旁能算得过账，在大多数街区则不行。需求也有限：即使在 2021 年这个被预测为至少自 1999 年以来最好的年份，芝加哥市中心预计也只能多租出约 6,500 套公寓。环线的分区已经允许超高层；挡住它们的是成本和融资。所以在模拟中，把中层楼和三至六户楼分散到全市，比把塔楼堆在少数几个地方能增加更多住房。',
    'Wieżowce ze stali i betonu kosztują ok. 65–71 dol. więcej za stopę kw. niż niższe budynki (badanie Terner Center projektów w Kalifornii) i potrzebują wind, głębokich fundamentów i dodatkowych zabezpieczeń przeciwpożarowych. Opłacają się w centrum i przy najruchliwszych stacjach, nie na większości kwartałów. Popyt też się kończy: nawet w 2021, który miał być najlepszym rokiem co najmniej od 1999, centrum Chicago miało wypełnić ok. 6500 nowych mieszkań. Strefa w Loop już pozwala na superwysokie wieże; hamują je koszty i finansowanie. Dlatego rozłożenie budynków średniowysokich i domów 3–6-rodzinnych po całym mieście daje w symulacji więcej mieszkań niż wieże stłoczone w kilku miejscach.'),
79: ('“They don\'t build them', '“Ya no los construyen como antes.”', '“现在不像以前那样盖房子了。”', '„Już się takich nie buduje.”'),
80: ("They can't. It's illegal", 'No pueden. Es ilegal en la mayor parte del terreno de la ciudad.', '没法盖。在城市大部分土地上这是违法的。', 'Nie można. Na większości ziemi w mieście jest to nielegalne.'),
81: ('The 2-flats and 3-flats', 'Los edificios de 2 y 3 departamentos que definen los barrios de Chicago están prohibidos hoy en gran parte de la ciudad. El 41% de Chicago tiene zonificación solo para casas unifamiliares o de dos departamentos (apenas el 11% permite tres departamentos o más), y cerca de un tercio de los lotes unifamiliares son más pequeños que el mínimo del código de zonificación, así que incluso una sola casa ahí necesita aprobación especial.',
    '定义芝加哥社区的双户楼和三户楼如今在城市大部分地方被禁止。芝加哥 41% 的土地只允许独栋房或双户楼（只有 11% 允许三户楼及以上），约三分之一的独栋地块小于分区法规的最小面积，所以那里即使盖一栋独立住宅也需要特别批准。',
    'Domy dwu- i trzyrodzinne, które tworzą dzielnice Chicago, są dziś zakazane na dużej części miasta. 41% Chicago ma strefę tylko dla domów jednorodzinnych lub dwurodzinnych (zaledwie 11% pozwala na trzy mieszkania i więcej), a ok. jedna trzecia działek jednorodzinnych jest mniejsza niż minimum z kodeksu, więc nawet pojedynczy dom wymaga tam specjalnej zgody.'),
82: ('“New luxury buildings', '“Los edificios de lujo nuevos hacen subir las rentas.”', '“新的豪华公寓楼会推高房租。”', '„Nowe luksusowe budynki podnoszą czynsze.”'),
83: ('Usually the opposite', 'Normalmente al revés: las rentas cercanas tienden a bajar.', '通常相反：附近的房租往往会下降。', 'Zwykle odwrotnie: czynsze w okolicy raczej spadają.'),
84: ('Higher-income renters', 'Los inquilinos de mayores ingresos que se mudan a un edificio nuevo, de otro modo competirían por departamentos más viejos cercanos. Un estudio de 11 ciudades de EE. UU. encontró que las rentas cerca de edificios nuevos en zonas de bajos ingresos quedaron 5–7% más bajas que las rentas un poco más lejos. En Nueva York, sumar 10% más viviendas en un radio de 500 pies bajó las rentas cercanas cerca de 1%.',
    '搬进新楼的高收入租户，否则就会去争附近的旧公寓。一项对美国 11 个城市的研究发现，低收入地区新楼附近的房租比稍远处低 5–7%。在纽约，500 英尺内住房增加 10%，附近房租下降约 1%。',
    'Zamożniejsi najemcy, którzy wprowadzają się do nowego budynku, inaczej konkurowaliby o starsze mieszkania w pobliżu. Badanie 11 miast USA wykazało, że czynsze przy nowych budynkach w uboższych okolicach były o 5–7% niższe niż nieco dalej. W Nowym Jorku 10% więcej mieszkań w promieniu 500 stóp obniżyło czynsze w pobliżu o ok. 1%.'),
86: ('“New homes only help', '“Las viviendas nuevas solo ayudan a los ricos.”', '“新房只对富人有帮助。”', '„Nowe mieszkania pomagają tylko bogatym.”'),
87: ('They help people further down', 'También ayudan a la gente más abajo en la escalera, unos años después.', '几年后，它们也会帮助收入更低的人。', 'Pomagają też ludziom niżej na drabinie, kilka lat później.'),
88: ('When someone moves into a new apartment', 'Cuando alguien se muda a un departamento nuevo, deja uno más viejo vacío, y la siguiente persona se muda a ese. Los investigadores siguieron estas cadenas de mudanzas: cada 100 viviendas nuevas a precio de mercado liberaron el equivalente de 45 a 70 viviendas en barrios de ingresos por debajo de la mediana, casi siempre en pocos años. Helsinki encontró algo parecido. Es lento y no reemplaza los subsidios para los ingresos más bajos.',
    '有人搬进新公寓，就会空出一套旧公寓，下一个人再搬进去。研究者追踪了这些搬迁链：每 100 套新的市价住房，会在收入低于中位数的社区腾出相当于 45–70 套住房，大多在几年之内。赫尔辛基的发现差不多。这个过程很慢，也不能取代对最低收入人群的补贴。',
    'Gdy ktoś wprowadza się do nowego mieszkania, zwalnia starsze, a do niego wprowadza się następna osoba. Badacze śledzili takie łańcuchy przeprowadzek: każde 100 nowych mieszkań rynkowych zwalniało odpowiednik 45–70 mieszkań w dzielnicach o dochodach poniżej mediany, zwykle w ciągu kilku lat. Helsinki dały podobny wynik. To powolne i nie zastępuje dopłat dla najuboższych.'),
91: ("“It's all Airbnb", '“Todo es culpa de Airbnb.”', '“全是 Airbnb 的错。”', '„To wszystko wina Airbnb.”'),
92: ('Short-term rentals are a small', 'Las rentas de corto plazo son una parte pequeña del problema.', '短租只是问题的一小部分。', 'Najem krótkoterminowy to mała część problemu.'),
93: ('Airbnbs take some homes', 'Los Airbnb sacan algunas viviendas del mercado, pero el efecto en la renta es pequeño: un aumento de 1% en los anuncios sube las rentas locales cerca de 0.018%. Las reglas que Chicago ya tiene redujeron los anuncios cerca de 16%. La ciudad tiene unos 11,200 anuncios; a la región le faltan más de 165,000 viviendas. Vale la pena regularlos, pero no pueden cerrar la brecha por sí solos.',
    'Airbnb 让一些住房离开了市场，但对房租的影响很小：房源每增加 1%，当地房租约上涨 0.018%。芝加哥现有规定已让房源减少约 16%。全市约有 11,200 个房源；整个地区缺少 165,000 多套住房。值得监管，但它本身无法补上缺口。',
    'Airbnb zabiera z rynku część mieszkań, ale wpływ na czynsze jest mały: 1% więcej ogłoszeń podnosi lokalne czynsze o ok. 0,018%. Obecne zasady w Chicago zmniejszyły liczbę ogłoszeń o ok. 16%. Miasto ma ok. 11 200 ogłoszeń; w regionie brakuje ponad 165 000 mieszkań. Warto to regulować, ale samo w sobie nie zamknie luki.'),
96: ('“Just build affordable', '“Mejor construyan vivienda asequible.”', '“直接建可负担住房就行了。”', '„Po prostu budujcie tanie mieszkania.”'),
97: ('Yes, and also', 'Sí, y además: el subsidio por sí solo no alcanza para pagarlo todo.', '要建，但光靠补贴付不起全部。', 'Tak, ale same dopłaty nie pokryją wszystkiego.'),
98: ('Subsidized affordable homes', 'Las viviendas asequibles subsidiadas son caras de construir: los proyectos de Chicago de 2025 costaron en promedio $678,870 por vivienda. A la ciudad le faltan unas 103,000 rentas asequibles, así que construirlas todas así costaría cerca de $70 mil millones. El subsidio importa más para los ingresos más bajos, pero una zonificación que permita construir más viviendas tiene que cargar con buena parte del peso.',
    '有补贴的可负担住房造价很高：芝加哥 2025 年的项目平均每套 678,870 美元。全市缺少约 103,000 套可负担出租房，全部这样建大约要 700 亿美元。补贴对最低收入人群最重要，但允许建更多住房的分区必须承担大部分重任。',
    'Dotowane tanie mieszkania są drogie w budowie: projekty w Chicago z 2025 kosztowały średnio 678 870 dol. za mieszkanie. Miastu brakuje ok. 103 000 tanich mieszkań na wynajem, więc zbudowanie ich wszystkich w ten sposób kosztowałoby ok. 70 mld dol. Dopłaty są najważniejsze dla najuboższych, ale dużą część ciężaru musi wziąć strefowanie, które pozwala budować więcej.'),
101: ("“Chicago's losing people", '“Chicago está perdiendo gente. ¿Para qué construir más?”', '“芝加哥人口在减少。为什么还要多建？”', '„Chicago traci mieszkańców. Po co budować więcej?”'),
102: ('Population barely moved', 'La población casi no cambió, pero el número de hogares creció.', '人口几乎没变，但家庭数量增加了。', 'Liczba ludności prawie się nie zmieniła, ale gospodarstw domowych przybyło.'),
103: ('Every household needs', 'Cada hogar necesita su propia vivienda, y más gente vive sola o en hogares más pequeños que antes. Así que el mismo número de personas necesita más viviendas. De 2000 a 2020 Chicago sumó 80,761 hogares pero solo 48,162 viviendas, la única parte de la región donde las viviendas se quedaron atrás de los hogares.',
    '每个家庭都需要自己的住房，而独居或小家庭比以前更多。所以同样多的人需要更多住房。2000 至 2020 年，芝加哥增加了 80,761 个家庭，却只增加了 48,162 套住房，是整个地区唯一住房增长落后于家庭增长的地方。',
    'Każde gospodarstwo domowe potrzebuje własnego mieszkania, a więcej osób niż kiedyś mieszka samotnie lub w mniejszych gospodarstwach. Ta sama liczba ludzi potrzebuje więc więcej mieszkań. W latach 2000–2020 Chicago przybyło 80 761 gospodarstw, ale tylko 48 162 mieszkania; to jedyna część regionu, gdzie mieszkania nie nadążyły za gospodarstwami.'),
104: ('“More density means', '“Más densidad significa más crimen y tráfico.”', '“密度越高，犯罪和交通越糟。”', '„Większa gęstość to więcej przestępstw i korków.”'),
105: ("Not in Chicago's crime data", 'No según los datos de crimen de Chicago, y cada vecino nuevo maneja un poco menos.', '芝加哥的犯罪数据并不支持这一点，而且每个新邻居开车都更少一点。', 'Nie według danych o przestępczości w Chicago, a każdy nowy sąsiad jeździ trochę mniej.'),
106: ('A Chicago study found dense blocks', 'Un estudio de Chicago encontró que las cuadras densas que mezclan viviendas y tiendas tienen menos crimen que las cuadras residenciales típicas, probablemente porque hay más gente alrededor para darse cuenta. En cuanto al tráfico, la gente en lugares más densos maneja un poco menos cada una, no más: en muchos estudios, 10% más densidad reduce el manejo por persona cerca de 0.4%. Una cuadra igual puede ver más viajes en total, pero las viviendas cerca del transporte suman menos coches que las mismas viviendas en el borde de la región.',
    '芝加哥的一项研究发现，住宅和商店混合的高密度街区犯罪比一般住宅街区少，可能因为周围有更多人能注意到。至于交通，住在密度更高地方的人每人开车略少，而不是更多：多项研究显示，密度提高 10%，人均开车减少约 0.4%。一个街区的总出行可能仍会增加，但靠近公交的住房比地区边缘的同样住房增加的车更少。',
    'Badanie z Chicago wykazało, że gęste kwartały łączące mieszkania i sklepy mają mniej przestępstw niż typowe kwartały mieszkaniowe, zapewne dlatego, że więcej ludzi jest w pobliżu i coś zauważy. Co do ruchu: w gęstszych miejscach każdy jeździ trochę mniej, nie więcej; według wielu badań 10% większa gęstość zmniejsza jazdę na osobę o ok. 0,4%. Kwartał może mieć więcej przejazdów w sumie, ale mieszkania przy komunikacji dokładają mniej aut niż te same mieszkania na skraju regionu.'),
109: ('“Upzoning doesn', '“Aumentar la zonificación no baja las rentas en realidad.”', '“上调分区其实并不能降低房租。”', '„Podnoszenie stref wcale nie obniża czynszów.”'),
110: ('Where cities did it at scale', 'Donde las ciudades lo hicieron a gran escala, las rentas subieron más lento o bajaron.', '在大规模这样做的城市，房租涨得更慢或下降了。', 'Tam, gdzie miasta zrobiły to na dużą skalę, czynsze rosły wolniej albo spadły.'),
111: ('Minneapolis allowed more homes', 'Minneapolis permitió más viviendas en más terreno: de 2017 a 2022 sus rentas subieron 1% mientras las del resto de Minnesota subieron 14%. Austin flexibilizó sus reglas y construyó cifras récord de viviendas, y la renta media bajó de $1,546 a $1,296 (2021–2026). Seis años después de que Auckland, Nueva Zelanda, aumentó la zonificación de cerca de tres cuartas partes de la ciudad, las rentas de 3 recámaras estaban un estimado de 22–35% por debajo de la tendencia que llevaban. Funciona despacio y junto con otros factores, pero la dirección es constante.',
    '明尼阿波利斯允许在更多土地上建更多住房：2017 至 2022 年其房租上涨 1%，明尼苏达州其他地区上涨 14%。奥斯汀放宽规定，住房建设创纪录，租金中位数从 1,546 美元降到 1,296 美元（2021–2026）。新西兰奥克兰上调了约四分之三城区的分区，六年后三居室房租估计比原有趋势低 22–35%。它起效慢，也和其他因素一起发挥作用，但方向是一致的。',
    'Minneapolis pozwoliło na więcej mieszkań na większej ilości ziemi: w latach 2017–2022 czynsze wzrosły tam o 1%, a w reszcie Minnesoty o 14%. Austin złagodził zasady, budował rekordowo dużo, a mediana czynszu spadła z 1546 do 1296 dol. (2021–2026). Sześć lat po tym, jak Auckland w Nowej Zelandii podniosło strefy na ok. trzech czwartych miasta, czynsze za mieszkania z 3 sypialniami były szacunkowo o 22–35% niższe niż wskazywał dotychczasowy trend. Działa powoli i razem z innymi czynnikami, ale kierunek jest stały.'),
115: ('“Just make every new building', '“Basta con exigir que cada edificio nuevo incluya más unidades asequibles.”', '“让每栋新楼都多包含一些可负担单元就行了。”', '„Wystarczy, by każdy nowy budynek miał więcej tanich mieszkań.”'),
116: ('Up to a point', 'Hasta cierto punto. Si se exige demasiado, se construyen menos edificios.', '在一定程度内可以。要求太高，盖起来的楼就少了。', 'Do pewnego stopnia. Przesadź, a budynków powstanie mniej.'),
117: ("Chicago's Affordable Requirements", 'La Ordenanza de Requisitos de Vivienda Asequible (ARO) de Chicago obliga a muchos edificios nuevos a rentar entre el 10% y el 20% de sus unidades por debajo del mercado. El resto del edificio paga esas unidades, así que un requisito más alto significa que menos proyectos salen las cuentas. Un modelo para Los Ángeles, donde las unidades asequibles atienden a hogares con el 30% del ingreso medio, encontró que la construcción total bajó cerca de 30% cuando el requisito subió del 11% al 25%, y la producción asequible tocó techo alrededor del 25%. Más allá de eso, bajan los dos tipos de vivienda. Los estudios de ciudades reales casi siempre encuentran efectos mucho menores, desde ninguna caída clara hasta 5–8% menos viviendas, así que el punto exacto de quiebre es incierto.',
    '芝加哥的《可负担住房要求条例》（ARO）要求许多新楼以低于市场的价格出租 10–20% 的单元。这些单元由楼内其他单元补贴，所以要求越高，算得过账的项目就越少。洛杉矶的可负担单元面向收入为中位数 30% 的家庭，那里的模型发现，要求从 11% 提高到 25% 时，总建设量下降约 30%，可负担住房的产出在 25% 左右达到上限。超过这个点，两类住房都会减少。对真实城市的研究大多发现影响小得多，从没有明显下降到住房少 5–8%，所以确切的转折点并不确定。',
    'Chicagowskie rozporządzenie o tanich mieszkaniach (ARO) każe wielu nowym budynkom wynajmować 10–20% lokali poniżej ceny rynkowej. Resztę budynku obciąża koszt tych lokali, więc wyższy wymóg oznacza, że mniej projektów się opłaca. Model dla Los Angeles, gdzie tanie lokale są dla gospodarstw z 30% mediany dochodu, wykazał, że całe budownictwo spadło o ok. 30%, gdy wymóg wzrósł z 11% do 25%, a liczba tanich mieszkań osiągnęła szczyt przy ok. 25%. Powyżej tego spadają oba rodzaje mieszkań. Badania prawdziwych miast zwykle znajdują znacznie mniejsze efekty, od braku wyraźnego spadku do 5–8% mniej mieszkań, więc dokładny punkt przełomu jest niepewny.'),
121: ('Great, 200 new neighbors', 'Genial, 200 vecinos nuevos y todos manejan por mi calle.', '好极了，200 个新邻居，每个都开车经过我家这条街。', 'Super, 200 nowych sąsiadów i każdy przejeżdża moją ulicą.'),
122: ('Neighbors near jobs and the L', 'Los vecinos cerca del trabajo y del L manejan menos. En más de 200 estudios de viajes, vivir cerca del empleo y del centro reduce el manejo de un hogar más que cualquier otra cosa. Cada familia que se muda aquí en lugar de al borde de la región significa menos coches en el camino en total, y Chicago ya no obliga a los edificios cerca del transporte a tener garaje.',
    '住在工作地点和 L 线附近的邻居开车更少。在 200 多项出行研究中，住得离工作和市中心近，比任何其他因素都更能减少一个家庭的开车。每有一个家庭搬到这里而不是地区边缘，路上的车总体就少一些，而且芝加哥已不再强制公交附近的楼建车库。',
    'Sąsiedzi blisko pracy i kolejki L jeżdżą mniej. W ponad 200 badaniach podróży mieszkanie blisko miejsc pracy i centrum zmniejsza jazdę gospodarstwa bardziej niż cokolwiek innego. Każda rodzina, która wprowadza się tutaj zamiast na skraj regionu, to w sumie mniej aut na drogach, a Chicago nie zmusza już budynków przy komunikacji do budowy garaży.'),
123: ('California (SB 743', 'California (SB 743, en todo el estado desde 2020) dejó de tratar "los coches esperando en los cruces" como daño ambiental y ahora mide el manejo total, lo que favorece construir dentro de la ciudad cerca del transporte.',
    '加州（SB 743，2020 年起全州实施）不再把"路口排队的车"当作环境危害，而是衡量总驾驶量，这有利于在公交附近的城区内建设。',
    'Kalifornia (SB 743, w całym stanie od 2020) przestała traktować „samochody czekające na skrzyżowaniach” jako szkodę dla środowiska i mierzy teraz całkowitą jazdę, co sprzyja zabudowie przy komunikacji.'),
126: ('I already circle the block', 'Ya doy vueltas a la cuadra veinte minutos. ¿Dónde se van a estacionar?', '我已经要绕街区转二十分钟了。他们把车停哪？', 'Już teraz krążę dwadzieścia minut wokół kwartału. Gdzie oni zaparkują?'),
127: ('Bundled garage parking', 'El estacionamiento en garaje incluido suma unos $1,700 al año (~17%) a la renta, y los inquilinos sin coche igual pagan unos $621 al año por él. Después de que Buffalo eliminó los mínimos de estacionamiento, los proyectos grandes construyeron 47% menos espacios de los que exigían las reglas anteriores, pero siguieron construyendo estacionamiento donde los compradores lo querían.',
    '捆绑的车库停车位让房租每年多出约 1,700 美元（约 17%），没有车的租户每年也要为此付约 621 美元。布法罗取消停车位最低要求后，大项目建的车位比旧规定少 47%，但在买家想要的地方仍然建了停车位。',
    'Parking w garażu w pakiecie dokłada do czynszu ok. 1700 dol. rocznie (~17%), a najemcy bez auta i tak płacą za niego ok. 621 dol. rocznie. Po zniesieniu minimów parkingowych w Buffalo duże projekty budowały o 47% mniej miejsc, niż wymagały stare zasady, ale nadal budowały parkingi tam, gdzie chcieli tego kupujący.'),
128: ('Buffalo scrapped minimums', 'Buffalo eliminó los mínimos en toda la ciudad en 2017. Chicago eliminó la exigencia cerca de la CTA y Metra en julio de 2025.', '布法罗在 2017 年于全市取消最低要求。芝加哥在 2025 年 7 月取消了 CTA 和 Metra 附近的强制要求。', 'Buffalo zniosło minima w całym mieście w 2017. Chicago zniosło wymogi przy CTA i Metrze w lipcu 2025.'),
132: ('Nobody moved here', 'Nadie se mudó aquí para vivir a la sombra de una caja de vidrio.', '没人搬来这里是为了住在玻璃盒子的阴影下。', 'Nikt się tu nie przeprowadził, żeby mieszkać w cieniu szklanego pudła.'),
133: ("Your neighborhood's character", 'El carácter de tu barrio son los edificios de tres departamentos y los edificios con patio que hoy es ilegal construir en la mayor parte del terreno de la ciudad: el 41% de Chicago tiene zonificación solo para casas unifamiliares o de dos departamentos, y apenas el 11% permite tres departamentos o más. En un experimento con encuestas, los edificios que coincidían con la altura y el estilo de su cuadra ganaron más apoyo tanto de propietarios como de inquilinos.',
    '你们社区的特色是三户楼和庭院式公寓楼，而这些如今在城市大部分土地上都是违法的：芝加哥 41% 的土地只允许独栋房或双户楼，只有 11% 允许三户楼及以上。在一项调查实验中，高度和风格与所在街区相符的楼，获得房主和租户更多支持。',
    'Charakter twojej dzielnicy to domy trzyrodzinne i kamienice z dziedzińcem, których dziś nie wolno budować na większości ziemi w mieście: 41% Chicago ma strefę tylko dla domów jedno- lub dwurodzinnych, a zaledwie 11% pozwala na trzy mieszkania i więcej. W eksperymencie ankietowym budynki pasujące wysokością i stylem do kwartału zyskiwały większe poparcie zarówno właścicieli, jak i najemców.'),
134: ('Portland (2021) allowed', 'Portland (2021) permitió hasta 4 viviendas por lote (6 con unidades asequibles) pero limitó el tamaño de los edificios. En el primer año, el 73% de las viviendas nuevas que no eran ADU fueron vivienda intermedia: de dúplex a cuádruplex del tamaño de una casa grande.',
    '波特兰（2021）允许每块地建最多 4 套住房（含可负担单元可建 6 套），但限制了建筑规模。第一年，73% 的非附属单元新住房是中间住房：大小相当于一栋大房子的双户到四户楼。',
    'Portland (2021) pozwolił na maks. 4 mieszkania na działce (6 z tanimi lokalami), ale ograniczył wielkość budynków. W pierwszym roku 73% nowych mieszkań poza domkami na podwórku to była zabudowa pośrednia: domy od dwu- do czterorodzinnych wielkości dużego domu.'),
138: ("That's my retirement fund", 'Ese es mi fondo de retiro y le están poniendo un bloque de departamentos al lado.', '那可是我的养老钱，你们却在旁边盖公寓楼。', 'To mój fundusz emerytalny, a wy stawiacie obok blok.'),
139: ("New apartments next door", 'Los departamentos nuevos al lado no hunden tu casa. En Nueva York, las torres nuevas no tuvieron un efecto significativo en el valor de las casas cercanas de 1 a 5 familias. Y cuando Chicago aumentó la zonificación cerca del transporte en 2015, los lotes rezonificados subieron de valor: más viviendas permitidas significa que tu terreno vale más.',
    '隔壁的新公寓不会让你的房子贬值。在纽约，新塔楼对附近 1–5 户住宅的价值没有显著影响。芝加哥 2015 年上调公交附近的分区后，被上调的地块升值了：允许建的住房越多，你的土地越值钱。',
    'Nowe mieszkania obok nie pogrążą twojego domu. W Nowym Jorku nowe wieże nie miały istotnego wpływu na wartość pobliskich domów 1–5-rodzinnych. A gdy Chicago podniosło strefy przy komunikacji w 2015, wartość tych działek wzrosła: więcej dozwolonych mieszkań oznacza, że twoja ziemia jest więcej warta.'),
140: ("Houston's small-lot reforms", 'Las reformas de lotes pequeños de Houston (1998, 2013) permitieron a los dueños dividir y vender, y siguieron unas 80,000 viviendas en lotes pequeños. Aumentar la zonificación da opciones a los dueños, no solo a los vecinos.',
    '休斯敦的小地块改革（1998、2013）让业主可以分割和出售土地，随后建起了约 80,000 套小地块住房。上调分区给业主更多选择，而不只是给邻居。',
    'Reformy małych działek w Houston (1998, 2013) pozwoliły właścicielom dzielić je i sprzedawać, po czym powstało ok. 80 000 domów na małych działkach. Podniesienie strefy daje możliwości właścicielom, nie tylko sąsiadom.'),
144: ('First comes the luxury tower', 'Primero llega la torre de lujo, luego mi casero me duplica la renta.', '先来一栋豪华塔楼，然后我的房东就把房租翻倍。', 'Najpierw luksusowa wieża, potem właściciel podwaja mi czynsz.'),
145: ('New buildings lower rents nearby', 'Los edificios nuevos bajan las rentas cercanas. En 11 ciudades de EE. UU., los edificios grandes nuevos en zonas de bajos ingresos redujeron las rentas cercanas 5–7%. En Nueva York, cada 10% más de viviendas cercanas bajó las rentas cerca de 1%. Austin construyó a un ritmo récord y su renta media bajó de $1,546 a $1,296.',
    '新楼会降低附近的房租。在美国 11 个城市，低收入地区的大型新楼让附近房租下降 5–7%。在纽约，附近住房每增加 10%，房租下降约 1%。奥斯汀以创纪录的速度建房，租金中位数从 1,546 美元降到 1,296 美元。',
    'Nowe budynki obniżają czynsze w okolicy. W 11 miastach USA duże nowe budynki w uboższych okolicach obniżyły pobliskie czynsze o 5–7%. W Nowym Jorku każde 10% więcej mieszkań w pobliżu obniżało czynsze o ok. 1%. Austin budował w rekordowym tempie, a mediana czynszu spadła z 1546 do 1296 dol.'),
146: ('Oregon (2019) paired', 'Oregón (2019) combinó la estabilización de rentas en todo el estado con legalizar dúplex en todas las ciudades de 10,000 habitantes o más. Construir más y proteger a los inquilinos: no hay que elegir uno.',
    '俄勒冈州（2019）把全州房租稳定措施与在所有 1 万人以上城市合法化双户住宅结合起来。多建房和保护租户，不必二选一。',
    'Oregon (2019) połączył stanową stabilizację czynszów z legalizacją domów dwurodzinnych w każdym mieście powyżej 10 000 mieszkańców. Budować więcej i chronić najemców: nie trzeba wybierać.'),
149: ('Our schools are already packed', 'Nuestras escuelas ya están llenas. ¿Adónde van a ir todos esos niños?', '我们的学校已经很挤了。这么多孩子去哪上学？', 'Nasze szkoły już są pełne. Gdzie pójdą te wszystkie dzieci?'),
150: ("There's room. CPS", 'Hay espacio. CPS tiene lugar para unos 450,000 estudiantes e inscribe a unos 306,000, y Chicago tiene 875,000 personas menos que en 1950: las escuelas, las tuberías y los trenes se construyeron para una ciudad más grande. Los departamentos nuevos suman pocos niños: unos 10 en edad escolar por cada 100 viviendas de renta nuevas. Más vecinos ayudan a mantener abiertas las escuelas medio vacías.',
    '有空位。芝加哥公立学校（CPS）可容纳约 45 万名学生，实际注册约 30.6 万名，芝加哥人口比 1950 年少 87.5 万：学校、管道和列车都是为更大的城市建的。新公寓带来的孩子很少：每 100 套新出租房约有 10 名学龄儿童。更多邻居有助于让半空的学校继续开下去。',
    'Miejsce jest. CPS ma miejsca dla ok. 450 000 uczniów, a zapisanych jest ok. 306 000, a Chicago ma o 875 000 mieszkańców mniej niż w 1950: szkoły, rury i pociągi zbudowano dla większego miasta. Nowe mieszkania dodają niewiele dzieci: ok. 10 w wieku szkolnym na 100 nowych mieszkań na wynajem. Więcej sąsiadów pomaga utrzymać na wpół puste szkoły.'),
151: ('Montgomery County, MD (2020)', 'El condado de Montgomery, MD (2020) eliminó las congelaciones de construcción por escuelas y en su lugar cobró cuotas en las zonas llenas; la mayor parte del aumento de matrícula venía de casas existentes que pasaban a familias jóvenes.',
    '马里兰州蒙哥马利县（2020）取消了因学校拥挤而冻结建设的做法，改为在拥挤地区收费；大部分入学人数增长来自现有房屋转手给年轻家庭。',
    'Hrabstwo Montgomery, MD (2020) zniosło wstrzymywanie budów z powodu szkół i zamiast tego pobiera opłaty w zatłoczonych rejonach; większość wzrostu liczby uczniów brała się z istniejących domów przechodzących w ręce młodych rodzin.'),
156: ('More strangers, more break-ins', 'Más extraños, más robos. Solo digo lo que todos piensan.', '陌生人越多，入室盗窃越多。我只是说出大家心里想的。', 'Więcej obcych, więcej włamań. Mówię tylko, co wszyscy myślą.'),
157: ('Studies of subsidized housing', 'Los estudios de la vivienda subsidiada, la que más despierta este miedo, no encuentran evidencia de que aumente el crimen; en las zonas más pobres, el crimen violento bajó. Un estudio de Chicago encontró que las cuadras densas y de uso mixto tienen menos crimen: más ojos en la calle.',
    '对补贴住房（最容易引起这种担心的那类）的研究没有发现它会增加犯罪的证据；在最贫困的地区，暴力犯罪反而下降了。芝加哥的一项研究发现，密集的混合用途街区犯罪更少：街上看着的眼睛更多。',
    'Badania mieszkań dotowanych, które budzą ten strach najbardziej, nie znajdują dowodów, że zwiększają przestępczość; w najbiedniejszych rejonach przestępstwa z użyciem przemocy spadły. Badanie z Chicago wykazało, że gęste kwartały o mieszanej funkcji mają mniej przestępstw: więcej oczu na ulicy.'),
158: ("After New Jersey's Mount Laurel", 'Después de las peleas por Mount Laurel en Nueva Jersey, un estudio de Princeton sobre el desarrollo asequible no encontró efecto en los impuestos, el crimen ni el valor de las propiedades del pueblo.',
    '在新泽西州的芒特劳雷尔之争之后，普林斯顿的一项研究发现，这个可负担住房项目对该镇的税收、犯罪和房产价值都没有影响。',
    'Po sporach o Mount Laurel w New Jersey badanie z Princeton nie wykazało wpływu tamtejszej inwestycji z tanimi mieszkaniami na podatki, przestępczość ani wartość nieruchomości w miasteczku.'),
163: ('$3,000 studios with a dog spa', 'Estudios de $3,000 con spa para perros. ¿Para quién es esto exactamente?', '带宠物狗水疗的 3,000 美元单间公寓。这到底是给谁住的？', 'Kawalerki za 3000 dol. ze spa dla psów. Dla kogo to właściwie jest?'),
164: ('New buildings start chains', 'Los edificios nuevos inician cadenas de mudanzas. Cada 100 viviendas nuevas a precio de mercado liberan el equivalente de 45–70 viviendas en barrios de ingresos por debajo de la mediana en pocos años; Helsinki encontró unas 66. Es lento y no reemplaza el subsidio para los ingresos más bajos.',
    '新楼会引发搬迁链。每 100 套新的市价住房，几年内会在收入低于中位数的社区腾出相当于 45–70 套住房；赫尔辛基的结果约为 66 套。这很慢，也不能取代对最低收入人群的补贴。',
    'Nowe budynki uruchamiają łańcuchy przeprowadzek. Każde 100 nowych mieszkań rynkowych zwalnia w ciągu kilku lat odpowiednik 45–70 mieszkań w dzielnicach o dochodach poniżej mediany; w Helsinkach wyszło ok. 66. To powolne i nie zastępuje dopłat dla najuboższych.'),
165: ('Minneapolis upzoned corridors', 'Minneapolis aumentó la zonificación en los corredores y eliminó los mínimos de estacionamiento: la vivienda creció 12% de 2017 a 2022 mientras las rentas subieron 1%, contra 14% en el resto de Minnesota.',
    '明尼阿波利斯上调走廊分区并取消停车位最低要求：2017–2022 年住房增加 12%，房租上涨 1%，明尼苏达州其他地区为 14%。',
    'Minneapolis podniosło strefy przy korytarzach i zniosło minima parkingowe: w latach 2017–2022 liczba mieszkań wzrosła o 12%, a czynsze o 1%, wobec 14% w reszcie Minnesoty.'),
166: ('My alderperson should decide', 'Mi concejal debería decidir qué va en mi cuadra. Eso es democracia.', '我的市议员应该决定我们街区建什么。这才是民主。', 'To mój radny powinien decydować, co stanie w moim kwartale. To jest demokracja.'),
167: ('Case-by-case vetoes', 'Los vetos caso por caso hacen que cada edificio sea una pelea. HUD concluyó en 2023 que la prerrogativa de los concejales bloqueaba la vivienda asequible (retiró la conclusión en 2025). La ley de agilización de California abarcó más de 18,000 viviendas propuestas en sus primeros años, casi todas asequibles; el aumento de zonificación en toda Auckland sumó unas 21,800 viviendas extra.',
    '逐案否决让每栋楼都成了一场战斗。HUD 在 2023 年认定市议员特权阻碍了可负担住房（2025 年撤回这一结论）。加州的简化审批法在头几年覆盖了 18,000 多套拟建住房，大多是可负担住房；奥克兰全市上调分区多建了约 21,800 套住房。',
    'Weta w każdej sprawie z osobna sprawiają, że każdy budynek to walka. HUD uznał w 2023, że przywilej radnych blokuje tanie mieszkania (wycofał to ustalenie w 2025). Kalifornijska ustawa o przyspieszeniu objęła w pierwszych latach ponad 18 000 proponowanych mieszkań, głównie tanich; podniesienie stref w całym Auckland dało ok. 21 800 dodatkowych mieszkań.'),
168: ('Austin legalized 3 homes', 'Austin legalizó 3 viviendas por lote (2023) y los lotes pequeños (2024); con construcción récord, la renta media bajó de $1,546 a $1,296 (2021–2026).', '奥斯汀合法化了每块地 3 套住房（2023）和小地块（2024）；在创纪录的建设中，租金中位数从 1,546 美元降到 1,296 美元（2021–2026）。', 'Austin zalegalizował 3 mieszkania na działce (2023) i małe działki (2024); przy rekordowym budownictwie mediana czynszu spadła z 1546 do 1296 dol. (2021–2026).'),
171: ("I'm all for housing", 'Estoy a favor de la vivienda. Pero no aquí. En algún lugar más apropiado.', '我完全支持建房。只是别建在这里。换个更合适的地方。', 'Jestem za mieszkaniami. Tylko nie tutaj. Gdzieś w bardziej odpowiednim miejscu.'),
172: ('Who shows up decides', 'Decide quien se presenta. En 97 pueblos de Massachusetts, el 63% de quienes hablaron en reuniones sobre vivienda se opuso a los proyectos y el 15% los apoyó, y era mucho más probable que fueran propietarios que los votantes en general.',
    '谁到场谁决定。在马萨诸塞州 97 个城镇的住房会议上，63% 的发言者反对项目，15% 支持，而且发言者是房主的可能性比一般选民高得多。',
    'Decydują ci, którzy przychodzą. W 97 miasteczkach Massachusetts 63% mówców na zebraniach w sprawie mieszkań sprzeciwiało się projektom, a 15% je popierało; mówcy znacznie częściej niż ogół wyborców byli właścicielami domów.'),
173: ("Massachusetts' MBTA Communities", 'La ley MBTA Communities de Massachusetts (2021) exige a 177 pueblos con transporte permitir departamentos por derecho. Para enero de 2026, 165 habían cumplido, siguieron proyectos de casi 7,000 viviendas y el estado demandó a 9 que se resistían.',
    '马萨诸塞州的《MBTA 社区法》（2021）要求 177 个有公交的城镇允许无需审批建公寓。到 2026 年 1 月，165 个已经遵守，随后出现了近 7,000 套住房的项目，州政府起诉了 9 个拒不执行的城镇。',
    'Ustawa MBTA Communities w Massachusetts (2021) wymaga, by 177 miasteczek z komunikacją dopuściło mieszkania z mocy prawa. Do stycznia 2026 165 się dostosowało, pojawiły się projekty na prawie 7000 mieszkań, a stan pozwał 9 opornych.'),
})
